# CFA (plainCfa): one factor or several correlated factors, one group.
# Options, results and panel: jamovi/plainCfa.*.yaml (generated by
# tools/gen_yaml.py); jmvtools generates R/plainCfa.h.R. The statistics are in
# factorWiz() (R/engine-cfa.R). Lifecycle as in R/jmv-invariance.R: nothing is
# fitted until `Run analysis` is ticked, and the result is cached as the state
# of the `fit` table, so the output options never refit.

plainCfaClass <- if (requireNamespace("jmvcore", quietly = TRUE)) R6::R6Class(
  "plainCfaClass",
  inherit = plainCfaBase,
  private = list(
    .run = function() {
      opt <- self$options
      out <- self$results
      factors <- psw_jmv_factors(opt$factors)
      if (!psw_jmv_ready(factors)) {
        psw_jmv_todo(out$todo, c(
          "Drag the items of each factor into its box (at least three items for a single factor). Use <b>Add New Factor</b> for more factors; they are allowed to correlate.",
          "Then tick <b>Run analysis</b>. Nothing is fitted before that, so you can set every option first."))
        return(invisible())
      }
      res <- out$fit$state
      if (is.null(res)) {
        if (!opt$run) {
          prep <- tryCatch(psw_prepare(self$data, factors, type = opt$type),
                           error = function(e) jmvcore::reject(conditionMessage(e), code = ""))
          est <- if (opt$estimator == "auto") (if (prep$type == "ordinal") "WLSMV" else "MLR") else opt$estimator
          psw_jmv_todo(out$todo, c(
            sprintf("Ready: %d factor(s), %d items treated as <b>%s</b>, N = %d, estimator %s.",
                    length(factors), length(unlist(factors)), prep$type, nrow(prep$data), est),
            "Tick <b>Run analysis</b> to fit the model."), prep$notes)
          return(invisible())
        }
        higher <- trimws(opt$higherName)
        res <- tryCatch(
          factorWiz(self$data, factors, type = opt$type, estimator = opt$estimator, missing = opt$missing,
                    residuals = lapply(opt$resCov, function(p) c(p$i1, p$i2)),
                    higher = if (opt$secondOrder) (if (nzchar(higher)) higher else "General") else NULL),
          error = function(e) jmvcore::reject(conditionMessage(e), code = ""))
        out$fit$setState(res)
      }
      psw_jmv_todo(out$todo)
      info <- res$info
      one <- length(info$factors) < 2L

      f <- res$fit
      psw_jmv_fill(out$fit, list(list(chisq = f$chisq, df = round(f$df), p = f$pvalue, cfi = f$cfi, tli = f$tli,
                                      rmsea = f$rmsea, rmseaLo = f$rmsea.lo, rmseaHi = f$rmsea.hi, srmr = f$srmr)))
      if (isTRUE(opt$highlight)) psw_jmv_flag_fit(out$fit, f)
      out$fit$setNote("info", sprintf(
        "N = %d. Estimator: %s. Items treated as %s. Missing values: %s. %s lavaan %s.",
        info$n, info$estimator, info$type, info$missing, paste0(psw_jmv_variant_text(info$variant), ""),
        info$lavaan), init = FALSE)
      psw_jmv_notes(out$fit, res$notes)

      if (opt$showLoadings) {
        l <- res$loadings
        psw_jmv_fill(out$loadings, lapply(seq_len(nrow(l)), function(i)
          list(factor = l$factor[i], item = l$item[i], est = l$est[i], se = l$se[i], p = l$p[i],
               std = l$std[i], r2 = l$r2[i])))
        if (opt$highlight) for (i in seq_len(nrow(l)))
          if (isTRUE(abs(l$std[i]) < 0.40))
            out$loadings$addFormat(rowNo = i, col = "std", format = jmvcore::Cell.NEGATIVE)
        out$loadings$setNote("what", paste0(
          "Factor variances are fixed to 1. R\u00B2: the share of the item's variance explained by its factor",
          if (info$type == "ordinal") " (for ordinal items, the variance of the latent response)" else "", ".",
          if (opt$highlight) " In red: standardized loadings below .40." else ""), init = FALSE)
      }

      one <- one || !is.null(res$higher)   # no free factor correlations in a second-order model
      out$cors$setVisible(opt$showCors && !one)
      if (opt$showCors && !one) {
        cc <- res$cors
        psw_jmv_fill(out$cors, lapply(seq_len(nrow(cc)), function(i)
          list(factor1 = cc$factor1[i], factor2 = cc$factor2[i], r = cc$r[i], p = cc$p[i])))
      }

      if (opt$showRel) {
        rl <- res$reliability
        psw_jmv_fill(out$rel, lapply(seq_len(nrow(rl)), function(i) as.list(rl[i, , drop = FALSE])))
        if (isTRUE(opt$highlight)) {
          for (i in seq_len(nrow(rl))) {
            if (isTRUE(rl$alpha[i] < 0.70)) out$rel$addFormat(rowNo = i, col = "alpha", format = jmvcore::Cell.NEGATIVE)
            if (isTRUE(rl$omega[i] < 0.70)) out$rel$addFormat(rowNo = i, col = "omega", format = jmvcore::Cell.NEGATIVE)
            if (isTRUE(rl$ave[i] < 0.50)) out$rel$addFormat(rowNo = i, col = "ave", format = jmvcore::Cell.NEGATIVE)
          }
        }
        out$rel$setNote("what", paste0(
          "\u03B1: Cronbach's alpha of the items as scored. \u03C9: composite reliability implied by the model",
          if (info$type == "ordinal")
            "; with ordinal items it describes the latent responses, so it is usually higher than what the sum score achieves"
          else " for the sum score",
          ". AVE: mean squared standardized loading. Scale Check has more for a single scale.",
          if (isTRUE(opt$highlight)) " In red: \u03B1 or \u03C9 below .70, AVE below .50." else ""), init = FALSE)
      }

      out$methods$setVisible(opt$showMethods && length(info$factors) >= 2L)
      if (opt$showMethods && length(info$factors) >= 2L) {
        m <- res$correlations
        psw_jmv_fill(out$methods, lapply(seq_len(nrow(m)), function(i) as.list(m[i, , drop = FALSE])))
        out$methods$setNote("what", paste0(
          "The same correlation under different ways of scoring. Composite scores: means of the items, attenuated ",
          "by unreliability. Corrected composites: divided by the square root of the product of the two alphas. ",
          "CFA: correlation between the latent factors. Factor scores: correlations between scores estimated from ",
          "the CFA; regression scores of correlated factors are typically too strongly correlated, Bartlett scores ",
          "(continuous items only) too weakly."), init = FALSE)
      }

      if (opt$showMi) {
        s <- utils::head(res$suggestions, opt$miN)
        if (is.null(s) || !nrow(s)) {
          out$mi$setNote("none", "No modification indices are available for this model.", init = FALSE)
        } else {
          psw_jmv_fill(out$mi, lapply(seq_len(nrow(s)), function(i) as.list(s[i, , drop = FALSE])))
          out$mi$setNote("what", paste0(
            "MI: the expected drop in the model \u03C7\u00B2 if this one parameter were added. Expected value: the ",
            "standardized size it would take. These show where the model strains; adding parameters because their ",
            "MI is large fits the sample, not necessarily the population."), init = FALSE)
        }
      }

      fd <- psw_cfa_figure_data(res)
      psw_jmv_figures(out, opt, fd$loadings, fd$cors, resid = fd$resid, higher = res$higher,
                      fit = res$fit, estimator = info$estimator)

      # ---- additions to the model ----
      hi <- res$higher
      out$higher$setVisible(!is.null(hi))
      if (!is.null(hi)) {
        h <- hi$loadings
        out$higher$setTitle(paste("Loadings on", hi$name))
        psw_jmv_fill(out$higher, lapply(seq_len(nrow(h)), function(i)
          list(factor = h$factor[i], est = h$est[i], se = h$se[i], p = h$p[i], std = h$std[i], r2 = h$std[i]^2)))
        out$higher$setNote("what", paste0(
          "The factors load on one second-order factor instead of correlating freely. R\u00B2: the share of the ",
          "factor that the second-order factor explains."), init = FALSE)
      }
      rs <- res$residuals
      out$resid$setVisible(!is.null(rs))
      if (!is.null(rs))
        psw_jmv_fill(out$resid, lapply(seq_len(nrow(rs)), function(i) as.list(rs[i, , drop = FALSE])))
      invisible()
    },
    .diagram = function(image, ...) psw_jmv_diagram(image)
  )
)
